# Starcel sculpted from nothing on the skeleton and clips of the game's own export of it (sculptkit.py):
#   blender --background --factory-startup --python sculpts/starcel.py -- <the export's Starcel.glb> <out.glb>
#
# Carpathia's heron chick (No. 10121, Flying), from its picture (docs/art/reference/gemini/carpathia/10121-Starcel.jpg)
# and its brief (CP-dex-3-river-and-caves.md, 121). The game has no sculptor for it: its export is a body generated by
# rule, of which the skeleton, the clips and the size are kept and nothing of the shape.
# The design: a scrawny grey-blue heron chick standing hunched and grumpy on long yellow legs; a plump body with its
# back sloping down to a short tail, a big folded wing of darker blue-grey feathers over each flank, its long dark
# primaries hanging back past the tail; the neck tucked in a short S, its front a ragged bib of pale down; a round
# head carried forward and low with a scruffy crest of loose feathers standing up and back from the crown, dark grey
# with pale streaks; round white eyes with a small dark pupil under a heavy brow that cuts their top on a slope down
# toward the beak (the glower); a long yellow beak pointing forward and down; big yellow feet, three long toes forward
# and one back. The shallow water it stands in is scenery and is left out.
# The export stands its generated body 0.077 off the ground; the heron stands on it (see the report).
# The export's joints: body (0, 0, 0.347), tail (0, 0.203, 0.347), wings (+-0.161, -0.02, 0.419), head (0, -0.096,
# 0.432), legs (+-0.072, -0.02, 0.243). The neck and head go on `head` from its joint; the thighs and legs on leg{s}.
# Written to be grown from: starcarno.py imports it (sibling("starcel")) for the legs, feet, beak, eyes, feathers,
# wings and crest, with numbers of its own.
import os, sys, math
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
import numpy as np
from sculptkit import Kit, ell, tube, hull, srgb, inside, unit, tri, eye_look, outward, args, sibling

p_ = sibling("pidgey")
spike = p_.spike

GREY, WING, DARK, PALE = "#8E9EB0", "#647A92", "#47596D", "#D7DFE9"
CROWN, BEAK, BEAK_DARK, FOOT, CLAW = "#56697E", "#E6BE4C", "#B88A2C", "#E2C35E", "#8A7440"
INK, PUPIL, SCLERA = "#1E2632", "#151820", "#F4F6F2"


def on_ell(c, r, d):
    c, r, d = np.array(c, float), np.array(r, float), unit(*d)
    p = c + d / np.linalg.norm(d / r)
    n = (p - c) / (r * r)
    return p, n / np.linalg.norm(n)


def board(k):
    V = np.array([v.co[:] for v in k.ob.data.vertices])
    a = math.radians(31.5)
    proj = V[:, 0] * math.cos(a) + V[:, 1] * math.sin(a)
    h, w, l = V[:, 2].max(), np.ptp(V[:, 0]), np.ptp(V[:, 1])
    sq = 1.3 * max(h, 0.85 * max(w, l))
    print("KIT: board: shows %.3f in a square of %.3f (%.2f); four corners %.3f (%.2f)" %
          (np.ptp(proj), sq, np.ptp(proj) / sq, 0.853 * w + 0.522 * l, (0.853 * w + 0.522 * l) / sq))


def rotm(rot):
    """The turn ell() gives a part (degrees about x, y, z) as a matrix: world = local @ m.T."""
    from mathutils import Euler
    return np.array(Euler([math.radians(r) for r in rot]).to_matrix())


class Cfg:
    """Starcel's numbers; starcarno.py makes a copy and changes them. A heron's body is a slim oval carried tilted,
    breast up and tail down (35 degrees), about twice as long as deep."""
    BODY_C, BODY_R, BODY_ROT = (0.0, 0.02, 0.4), (0.095, 0.168, 0.09), (-35, 0, 0)
    HEAD_C, HEAD_R = np.array([0.0, -0.172, 0.552]), np.array([0.064, 0.072, 0.06])
    # the neck hunched into the shoulders in a tight S, the head carried low and forward
    NECK = [(0.0, -0.075, 0.47), (0.0, -0.135, 0.49), (0.0, -0.118, 0.52), (0.0, -0.152, 0.548)]
    NECK_R = [0.05, 0.043, 0.04, 0.04]
    BEAK_LEN, BEAK_R, BEAK_DIR = 0.17, 0.022, unit(0, -1, -0.78)
    EYE_DIR, EYE_HALF, PUPIL_R = unit(0.64, -0.58, 0.3), 0.028, 0.36
    BROW = (0.22, 0.42)                       # the brow's cut: v above BROW[0] + BROW[1] * u is brow
    # each leg: the upper leg angled forward to a knobbed joint at mid height, the shin back from it; the two legs a
    # little apart in depth, as a wader stands
    HIP_Z, LEG_X, JOINT_Z, LEG_R = 0.32, 0.062, 0.165, (0.022, 0.019, 0.017)
    JOINT_FWD, STAGGER, KNOB = 0.042, 0.028, 1.36
    TOE_LEN, TOE_R = 0.08, 0.0115
    WING_C, WING_R, WING_ROT = (0.065, 0.045, 0.415), (0.036, 0.165, 0.078), (-35, 0, 0)
    MANTLE_C, MANTLE_R, MANTLE_ROT = (0.0, 0.05, 0.452), (0.062, 0.14, 0.042), (-35, 0, 0)
    PRIMARIES = 4
    PRIM_ROOT, PRIM_TIP = (0.066, 0.12, 0.355), (0.05, 0.27, 0.19)
    TAIL_ROOT, TAIL_TIP = (0.0, 0.15, 0.315), (0.0, 0.25, 0.225)
    COLOURS = dict(grey=GREY, wing=WING, dark=DARK, pale=PALE, crown=CROWN, edge="#93A6BA")


# --- the family's parts --------------------------------------------------------------------------------------------
def leg(k, cfg, side, s, colour=FOOT):
    """A long yellow leg with a knobbed joint, under a feathered thigh, on a big foot of three toes and one back."""
    x = cfg.LEG_X * s
    y0 = -cfg.STAGGER * s                                    # the +X leg a little ahead, the other behind
    top = np.array([x, y0 + 0.02, cfg.HIP_Z])
    joint = np.array([x * 1.02, y0 + 0.02 - cfg.JOINT_FWD, cfg.JOINT_Z])
    ankle = np.array([x * 1.05, y0, 0.026])
    k.add(f"leg{side}", outward(tube([top, joint], [cfg.LEG_R[0], cfg.LEG_R[1]], seg=14, per=6)), colour,
          f"leg{side}", fuse=False, surface="scales")
    k.add(f"shin{side}", outward(tube([joint, ankle], [cfg.LEG_R[1], cfg.LEG_R[2]], seg=14, per=6)), colour,
          f"leg{side}", fuse=False, surface="scales")
    k.add(f"knee{side}", outward(ell(joint, (cfg.LEG_R[1] * cfg.KNOB,) * 3)), colour, f"leg{side}", fuse=False,
          surface="scales")
    for j, (yaw, ln) in enumerate(((-28, 1.0), (0, 1.12), (28, 1.0), (180, 0.5))):
        t = math.radians(yaw + 8 * s)
        d = np.array([math.sin(t) * s, -math.cos(t), 0.0])
        a = ankle + np.array([0, 0, -0.012])
        L = cfg.TOE_LEN * ln
        tip = a + d * L + np.array([0, 0, -0.006])
        k.add(f"toe{j}{side}", outward(tube([a, a + d * L * 0.55, tip], [cfg.TOE_R * 1.15, cfg.TOE_R, cfg.TOE_R * 0.8],
                                            seg=12, per=4)), colour, f"leg{side}", fuse=False, surface="scales")
        e = tip + d * cfg.TOE_R * 0.4
        n = np.cross(d, (0, 0, 1.0))
        k.add(f"claw{j}{side}", hull([e + n * cfg.TOE_R * 0.7, e - n * cfg.TOE_R * 0.7,
                                       e + np.array([0, 0, cfg.TOE_R * 0.9]), e + np.array([0, 0, -cfg.TOE_R * 0.3]),
                                       e + d * cfg.TOE_R * 2.2 + np.array([0, 0, -cfg.TOE_R * 0.5])]),
              CLAW, f"leg{side}", fuse=False, surface="shell")
    k.add(f"thigh{side}", ell((x * 0.95, y0 + 0.02, cfg.HIP_Z + 0.035), (0.032, 0.04, 0.042)), cfg.COLOURS["grey"],
          f"leg{side}")


def beak(k, cfg, colour=BEAK):
    """A long dagger of a beak, deeper than wide at its root, pointing forward and down."""
    root = cfg.HEAD_C + np.array([0.0, -cfg.HEAD_R[1] * 0.72, -cfg.HEAD_R[2] * 0.25])
    tip = root + cfg.BEAK_DIR * cfg.BEAK_LEN
    pts = [root, root + (tip - root) * 0.35, root + (tip - root) * 0.72, tip]
    r = cfg.BEAK_R
    V, F = tube(pts, [r, r * 0.72, r * 0.42, r * 0.12], seg=16, per=6)
    V = V.copy()
    t = np.clip((V - root) @ cfg.BEAK_DIR / cfg.BEAK_LEN, 0, 1)
    V[:, 0] = root[0] + (V[:, 0] - root[0]) * (0.72 + 0.1 * t)
    k.add("beak", outward((V, F)), colour, "head", fuse=False, surface="shell")
    # the gape: a darker line along the bill's sides, a thin plate a hair proud of it
    a, b = root + cfg.BEAK_DIR * 0.01, root + cfg.BEAK_DIR * cfg.BEAK_LEN * 0.55
    for s in (1, -1):
        off = np.array([r * 0.74 * s, 0, -r * 0.05])
        k.add("gape", outward(tube([a + off, b + off * 0.55], [r * 0.16, r * 0.1], seg=8, per=3)), BEAK_DARK,
              "head", fuse=False, surface="shell")


def heron_eye(cfg, brow):
    """A round white eye with a small dark pupil and a dark rim, under a brow sloping down toward the beak."""
    S, K, P, W = srgb(SCLERA), srgb(INK), srgb(PUPIL), np.ones(3)
    def look(u, v):
        c = np.tile(S, (len(u), 1))
        c[u * u + v * v > 0.83 ** 2] = K
        c[(u + 0.16) ** 2 + (v + 0.06) ** 2 < cfg.PUPIL_R ** 2] = P
        c[(u - 0.02) ** 2 + (v - 0.12) ** 2 < 0.11 ** 2] = W
        return c
    def state_look(state, lid):
        base = eye_look(state, look, lid, K, line=0.17)
        lo, slope = cfg.BROW
        if state == "Fierce":
            lo -= 0.14
        def f(u, v):
            c = base(u, v)
            edge = lo + slope * u
            c[v > edge] = srgb(brow)
            c[np.abs(v - edge) < 0.09] = K
            return c
        return f
    return state_look


def eyes(k, cfg):
    ep, en = on_ell(cfg.HEAD_C, cfg.HEAD_R, cfg.EYE_DIR)
    lid = srgb(cfg.COLOURS["grey"])
    state_look = heron_eye(cfg, cfg.COLOURS["crown"])
    def lay(state):
        k.decal(ep, en, (cfg.EYE_HALF, cfg.EYE_HALF), state_look(state, lid), eps=0.002, rings=20, segs=56,
                mirror=True)
    return lay


def scallops(k, cfg, rows=3, line=0.0055):
    """The folded wing's feathers as rows of scalloped dark lines painted over its mass, each row's points hanging
    back and down, and the flight feathers under the last row dark: three bands read at the game's size."""
    col = cfg.COLOURS
    C, R, M = np.array(cfg.WING_C), np.array(cfg.WING_R), rotm(cfg.WING_ROT)
    def q(P):
        return ((np.stack([np.abs(P[:, 0]), P[:, 1], P[:, 2]], 1) - C) @ M) / R
    def local(P):
        Q = q(P)
        return Q[:, 1], Q[:, 2]
    def onwing(P):
        return inside(np.linalg.norm(q(P), axis=1) - 1.08, 0.02) * inside(C[0] * 0.6 - np.abs(P[:, 0]), 0.01)
    for r in range(rows):
        z0 = 0.5 - 0.48 * r
        def edge(P, z0=z0, r=r):
            y, z = local(P)
            scal = 0.2 * np.abs(np.sin(math.pi * (y / 0.62 + 0.5 * r)))
            return z - (z0 - 0.12 * y - scal)
        k.paint(lambda P, e=edge: inside(np.abs(e(P)) - line / cfg.WING_R[2], 0.015) * onwing(P), col["dark"],
                on=["wingmass", "mantle"])
        if r == rows - 1:
            k.paint(lambda P, e=edge: inside(e(P) + 0.06, 0.03) * onwing(P), col["dark"], on=["wingmass", "mantle"])


def wing(k, cfg):
    """A folded wing over each flank: a fused mass, rows of covert feathers laid back over it, long dark primaries
    hanging back past the tail, and a mantle over the back between the wings' tops so the back is one mass."""
    col = cfg.COLOURS
    k.add("wingmass", ell(cfg.WING_C, cfg.WING_R, rot=cfg.WING_ROT), col["wing"], "wing{s}", mirror=True)
    k.add("mantle", ell(cfg.MANTLE_C, cfg.MANTLE_R, rot=cfg.MANTLE_ROT), col["wing"], "body")
    scallops(k, cfg)
    for s, side in ((1, "R"), (-1, "L")):
        C, R = np.array(cfg.WING_C) * np.array([s, 1, 1]), np.array(cfg.WING_R)
        r0, r1 = np.array(cfg.PRIM_ROOT) * np.array([s, 1, 1]), np.array(cfg.PRIM_TIP) * np.array([s, 1, 1])
        for i in range(cfg.PRIMARIES):
            f = i / max(cfg.PRIMARIES - 1, 1)
            base = r0 + np.array([-0.012 * s * f, -0.03 * f, 0.03 * f])
            tip = r1 + np.array([-0.02 * s * f, -0.045 * f, 0.025 * f])
            k.add(f"primary{i}{side}", spike(base, tip, 0.05, 0.018, side=(0, 0.2, 1.0), at=0.4),
                  col["dark"] if i % 2 == 0 else col["wing"], f"wing{side}", fuse=False, surface="fur")


def tail(k, cfg):
    col = cfg.COLOURS
    r0, r1 = np.array(cfg.TAIL_ROOT), np.array(cfg.TAIL_TIP)
    for j, dx in enumerate((-0.035, 0.0, 0.035)):
        k.add("tailfeather", spike(r0 + np.array([dx * 0.5, 0, 0]), r1 + np.array([dx, 0, 0]), 0.045, 0.018,
                                   side=(1, 0, 0), at=0.45), col["dark"] if j != 1 else col["wing"], "tail",
              fuse=False, surface="fur")


# --- Starcel's own -------------------------------------------------------------------------------------------------
def crest(k, cfg):
    """The scruffy crest: fourteen tall, wild loose feathers standing up and back from the crown, dark grey with pale ones
    among them, their tips lifting clear and leaning a little toward +X."""
    C, R = cfg.HEAD_C, cfg.HEAD_R
    rs = np.random.RandomState(121)
    for i in range(14):
        a = -1.0 + 2.0 * i / 13
        p, n = on_ell(C, R, (0.85 * a, 0.25 + 0.5 * (1 - abs(a)), 1.0))
        base = p - n * 0.012
        d = unit(0.75 * a + 0.12 + 0.3 * rs.randn(), 0.8 + 0.5 * rs.rand(), 1.0 + 0.35 * rs.randn())
        ln = 0.13 + 0.07 * rs.rand() * (1.25 - abs(a))
        colour = PALE if i % 4 == 1 else (DARK if i % 2 else CROWN)
        k.add("crest", spike(base, base + d * ln, 0.036, 0.022, side=np.cross(d, (0, 1.0, 0)), at=0.3), colour,
              "head", fuse=False, surface="fur")
    # a few short shaggy feathers on the nape and the back of the neck
    for i, (x, y, z) in enumerate(((0.03, 0.0, 0.54), (-0.03, 0.0, 0.54), (0.045, 0.02, 0.5), (-0.045, 0.02, 0.5),
                                   (0.0, 0.03, 0.52))):
        b = np.array([x, cfg.HEAD_C[1] + 0.09 + y, z])
        d = unit(1.2 * x / 0.05 * 0.5, 1.0, -0.35)
        k.add("nape", spike(b, b + d * 0.055, 0.03, 0.018, side=(0, 0, 1.0)), GREY if i % 2 else WING, "head",
              fuse=False, surface="fur")


def bib(k, cfg):
    """The pale front of the neck and the breast, its down hanging in ragged pointed tufts of mixed lengths."""
    def m(P):
        x, y, z = P[:, 0], P[:, 1], P[:, 2]
        return inside(0.41 - z, 0.004) * inside(z - 0.56, 0.004) * inside(y + 0.1, 0.006) * inside(np.abs(x) - 0.07,
                                                                                                   0.006)
    k.paint(m, PALE, on=["neck", "body", "puff"])
    for x, y, z, r in ((0.0, -0.15, 0.465, 0.036), (0.03, -0.135, 0.455, 0.03), (-0.03, -0.135, 0.455, 0.03)):
        k.add("puff", ell((x, y, z), (r, r * 0.8, r)), PALE, "body")
    rs = np.random.RandomState(1210)
    for i, a in enumerate(np.linspace(-55, 55, 8)):
        t = math.radians(a)
        z = 0.5 - 0.03 * (i % 3) - 0.03 * math.cos(t)
        base = np.array([0.05 * math.sin(t), -0.165 + 0.05 * (1 - math.cos(t)) + 0.01 * (i % 2), z])
        d = unit(0.45 * math.sin(t) + 0.15 * rs.randn(), -0.3 - 0.15 * rs.rand(), -1.0)
        ln = 0.055 + 0.035 * rs.rand()
        k.add("tuft", spike(base, base + d * ln, 0.034, 0.018, side=(math.cos(t), math.sin(t) * 0.3, 0), at=0.35),
              PALE if i % 3 else "#B9C7D7", "body", fuse=False, surface="fur")


def scruff(k, cfg):
    """Loose feathers standing off the back and hanging from the lower edges of the wings: all scruff, as drawn."""
    col = cfg.COLOURS
    rs = np.random.RandomState(1211)
    for i in range(6):
        f = i / 5
        x = (-1) ** i * (0.012 + 0.018 * rs.rand())
        base = np.array([x, -0.06 + 0.17 * f, 0.5 - 0.15 * f])
        d = unit(x * 6 + 0.15 * rs.randn(), 0.9, 0.55 - 0.3 * f + 0.2 * rs.randn())
        k.add("backtuft", spike(base, base + d * (0.06 + 0.03 * rs.rand()), 0.034, 0.018, side=(1, 0, 0), at=0.35),
              col["wing"] if i % 2 else col["grey"], "body", fuse=False, surface="fur")
    M = rotm(cfg.WING_ROT)
    for s_, side in ((1, "R"), (-1, "L")):
        for i in range(4):
            yl = -0.55 + 0.38 * i
            loc = np.array([0.7, yl, -0.75]) * np.array(cfg.WING_R)
            base = np.array(cfg.WING_C) + loc @ M.T
            base[0] *= s_
            d = unit(0.35 * s_, 0.5 + 0.2 * rs.rand(), -1.0)
            k.add(f"wingtuft{side}", spike(base, base + d * (0.05 + 0.025 * rs.rand()), 0.036, 0.018,
                                           side=(0, 1, 0), at=0.35), col["edge"] if i % 2 else col["wing"],
                  f"wing{side}", fuse=False, surface="fur")


def body(k, cfg):
    col = cfg.COLOURS
    k.add("body", ell(cfg.BODY_C, cfg.BODY_R, rot=cfg.BODY_ROT), col["grey"], "body")
    k.add("neck", tube(cfg.NECK, cfg.NECK_R), col["grey"], "head")
    k.add("head", ell(cfg.HEAD_C, cfg.HEAD_R), col["grey"], "head")
    # the crown and brow darker
    k.paint(lambda P: inside(cfg.HEAD_C[2] + 0.018 - P[:, 2], 0.006) * inside(np.linalg.norm(P - cfg.HEAD_C, axis=1)
                                                                              - 0.1, 0.004), col["crown"],
            on=["head"])


def starcel(src, out_path, cfg=Cfg):
    k = Kit(src, coat="fur")
    body(k, cfg)
    bib(k, cfg)
    scruff(k, cfg)
    wing(k, cfg)
    tail(k, cfg)
    crest(k, cfg)
    beak(k, cfg)
    for s, side in ((1, "R"), (-1, "L")):
        leg(k, cfg, side, s)
    k.build(voxel=0.0062, smooth=4, band=0.006, wband=0.05)
    board(k)
    k.eye_states(eyes(k, cfg))
    k.export(out_path)


if __name__ == "__main__":
    starcel(*args())
